//! Independent ORIGINAL source-seven preparation, then frozen Tracked policy.
//! Remaining actual registered NotFound includes have an explicit partial old
//! preparation role. No source bytes, parser errors or Tracked answers are faked.
pub use dq_analyze::{incr,pat,pat_match,tree,util};
#[path="../../dmb/shared/test_scratch.rs"]mod test_scratch;
// Only the nominal preparation loan differs. The frozen producer below is
// compiled byte-for-byte unchanged; every method reads the genuine old Sem.
mod sem{pub use dq_analyze::sem::Sem;pub mod gen{
 pub use dq_analyze::sem::gen::{GenOut,test_only_types,test_only,TEST_GUARD};
 pub struct GenCx<'a>{pub tree:&'a dq_analyze::tree::Tree,pub model:&'a super::Sem}
 impl<'a> GenCx<'a>{pub fn sem(&self)->Option<&'a super::Sem>{Some(self.model)}}
 pub trait Generator:Send+Sync{fn name(&self)->&'static str;fn output(&self)->&'static str;fn stage(&self)->u8{0}fn generate(&self,cx:&GenCx<'_>,out:&mut GenOut);}
}}
#[path="support/tracked_lists_original.rs"]mod original;
use sha1::Digest as _;
use std::{path::{Path,PathBuf,Component},io::{self,Write}};
const ROLES:[&str;7]=["sparse_slots","system_accessors","stats","actions","declare_ids","declare","ui_types"];
fn document(name:&str,filename:&str,body:&str)->String{let mut text=format!("// GENERATED by tools/analyze: `analyze gen {}`. Do not edit by hand; edit the declarations it reads.\n// Written to code/engine/_generated/{}; not committed: every build regenerates it (`analyze gen`).\n\n",name,filename);text.push_str(body);if !text.ends_with('\n'){text.push('\n')}text}
fn engine(root:&Path)->Result<dq_analyze::run::Engine,String>{dq_analyze::run::Engine::new(dq_analyze::run::registry(),dq_analyze::run::Options{root:root.to_path_buf(),scopes_from:Some(root.to_path_buf()),lints:vec!["sem/keys".into()],raw:true,no_cache:true,..Default::default()})}
fn safe_write(root:&Path,relative:&str,text:&str)->io::Result<()>{let relative=Path::new(relative);if relative.is_absolute()||relative.components().any(|p|matches!(p,Component::ParentDir|Component::RootDir|Component::Prefix(_))){return Err(io::Error::new(io::ErrorKind::InvalidInput,"oracle generator output escapes private scratch"))}let target=root.join(relative);std::fs::create_dir_all(target.parent().ok_or_else(||io::Error::other("output parent absent"))?)?;let mut file=std::fs::OpenOptions::new().create_new(true).write(true).open(target)?;file.write_all(text.as_bytes())}
fn main()->Result<(),Box<dyn std::error::Error>>{
 let frozen:[u8;20]=sha1::Sha1::digest(include_bytes!("support/tracked_lists_original.rs")).into();assert_eq!(frozen,[58,197,117,244,38,77,60,14,36,30,228,99,89,22,115,99,216,116,243,96],"immutable whole original producer changed");
 dq_analyze::sem::incremental::disable_capture();
 let fixture=PathBuf::from(std::env::args().nth(1).ok_or("bootstrap fixture root required")?);let fixture=if fixture.is_absolute(){fixture}else{std::env::current_dir()?.join(fixture)};let root=dm_preprocess::regions::canonical_path(&test_scratch::dir("original-generation-tracked"));std::fs::create_dir_all(root.join("code/tests"))?;std::fs::create_dir_all(root.join("code/sub"))?;
 for relative in ["deepquarry.dme","code/probe.dm","code/tests/tracked.dm","code/extra.dm"]{std::fs::copy(fixture.join(relative),root.join(relative))?;}
 let registry=dq_analyze::sem::gen::registry();let initial=engine(&root)?;let mut staged=Vec::new();
 // ALL seven judge the SAME initial tree. Writes start only after their loans
 // end; no native output or answer is supplied to this independent recipe.
 for name in ROLES{let generator=registry.iter().find(|g|g.name()==name).ok_or("original source producer absent")?;let cx=dq_analyze::sem::gen::GenCx::new(&initial.tree,&root);let mut output=dq_analyze::sem::gen::GenOut::default();generator.generate(&cx,&mut output);let files=if generator.output().is_empty(){generator.files(&cx,&mut output)}else{vec![(format!("{}/{}",dq_analyze::sem::gen::OUT_DIR,generator.output()),document(generator.name(),generator.output(),output.text()))]};
  if !output.diags.is_empty(){return Err(format!("original source-seven findings: {:?}",output.diags.iter().map(|d|(&d.rel,d.line,&d.msg)).collect::<Vec<_>>()).into())}let wire=serde_json::json!({"generator":name,"files":&files,"diagnostics":[]});println!("OLD_GENERATION_SOURCE_FILE={wire}");staged.push(files);
 }drop(initial);
 for files in staged{for(relative,text)in files{safe_write(&root,&relative,&text)?;}}
 let current=engine(&root)?;let observed=dq_analyze::sem::ObservedGenerationOmissions::probe(&root)?;if observed.paths().next().is_none(){return Err("fixture must retain genuine missing purpose outputs".into())}let model=dq_analyze::sem::Sem::build_generation_original(&root,&current.tree,observed)?;if !model.errors.is_empty(){return Err(format!("partial original parser errors: {:?}",model.errors).into())}
 let mut original_registry=Vec::new();original::register(&mut original_registry);let generator=&original_registry[0];let mut output=dq_analyze::sem::gen::GenOut::default();generator.generate(&sem::gen::GenCx{tree:&current.tree,model:&model},&mut output);let text=document(generator.name(),generator.output(),output.text());if text.matches("/// TRACKED(").count()!=6||output.diags.len()!=3{return Err("genuine original tracked fixture must exercise six rows and three ordered diagnostics".into())}let wire=serde_json::json!({"generator":"tracked_lists","files":[["code/engine/_generated/tracked_lists.dm",text]],"diagnostics":output.diags.iter().map(|d|serde_json::json!({"rel":d.rel,"line":d.line,"msg":d.msg})).collect::<Vec<_>>()});println!("OLD_GENERATION_TRACKED_FULL={wire}");drop(model);drop(current);
 // A nonregistered missing include remains an ORIGINAL parser error. Nothing
 // is filtered from errors; only observed registered negatives can be omitted.
 let mut manifest=std::fs::read_to_string(root.join("deepquarry.dme"))?;manifest.push_str("#include \"unrelated_missing.dm\"\n");std::fs::write(root.join("deepquarry.dme"),&manifest)?;let current=engine(&root)?;let observed=dq_analyze::sem::ObservedGenerationOmissions::probe(&root)?;let bad=dq_analyze::sem::Sem::build_generation_original(&root,&current.tree,observed)?;if !bad.errors.iter().any(|error|error.contains("unrelated_missing.dm")){return Err("unrelated missing include was hidden by generation preparation".into())}drop(bad);drop(current);
 manifest=manifest.strip_suffix("#include \"unrelated_missing.dm\"\n").ok_or("control manifest suffix absent")?.to_owned();std::fs::write(root.join("deepquarry.dme"),&manifest)?;let current=engine(&root)?;let observed=dq_analyze::sem::ObservedGenerationOmissions::probe(&root)?;safe_write(&root,"code/engine/_generated/tracked_lists.dm",wire["files"][0][1].as_str().ok_or("actual old output absent")?)?;let moved=dq_analyze::sem::Sem::build_generation_original(&root,&current.tree,observed)?;if !moved.errors.iter().any(|error|error.contains("appeared")){return Err("appeared registered output did not invalidate observed negative".into())}
 println!("OLD_GENERATION_PREPARATION_CONTROLS=PASS");Ok(())
}
